<?php if ($tab==='contents'): ?><td>#<?= (int)$row['id'] ?></td><td class="table-title"><strong><?= e($row['title']) ?></strong><small><?= dt((int)$row['created_at']) ?></small></td><td><?= t($row['kind']) ?> <span class="pill <?= e($row['status']) ?>"><?= t($row['status']) ?></span></td><td><?= t($row['access_level']) ?><br><?= e(price((int)$row['price_amount'],$row['price_currency'])) ?></td><td><div class="row"><a class="btn secondary small" href="<?= e(au('edit_content',['id'=>$row['id']])) ?>"><?= t('Edit') ?></a><a class="icon-button" href="<?= e(item_url($row)) ?>" aria-label="<?= t('Preview') ?>"><?= icon('eye') ?></a></div></td>
