<?php elseif ($tab==='orders'): ?><td class="table-title"><strong><?= e($row['title']) ?></strong><small><?= e($row['order_no']) ?></small></td><td>#<?= (int)$row['user_id'] ?><br><small><?= dt((int)$row['created_at'],'m.d H:i') ?></small></td><td><?= e(price((int)$row['amount'],$row['currency'])) ?><br><small><?= t($row['kind']) ?></small></td><td><span class="pill <?= e($row['status']) ?>"><?= t($row['status']) ?></span><small><?= t($row['fulfillment']) ?></small></td><td><details class="table-details"><summary><?= t('Details / actions') ?></summary><p><?= t('Gateway receipt') ?>: <?= e($row['gateway_trade_no']??'-') ?></p><?php $address=$a->commerce->address($row);if ($address): ?><p><?= e(implode(' / ',$address)) ?></p><?php endif ?><?php if ($row['delivery_cipher']): ?><pre><?= e($a->commerce->delivery($row)) ?></pre><?php endif ?><?php if ($row['status']==='paid' && $row['fulfillment']==='awaiting_shipment'): ?><?= form_start('admin_ship') . hidden('id',$row['id']) ?><?php field('tracking','Carrier and tracking number','','text',['required'=>'required']);button('Mark as shipped','secondary small','box'); ?></form><?php endif ?><?php if ($row['status']==='refund_requested' && (int)($row['sale_id']??0)>0): ?><a class="btn secondary small" href="<?= e($a->basePath.'/admin/index.php?tab=service') ?>"><?= t('After-sales & refunds') ?></a><?php elseif ($row['status']==='refund_requested'): $meta=json_decode($row['metadata'],true); ?><p><?= t('Refund reason') ?>: <?= e($meta['refund_reason']??'') ?></p><?= form_start('admin_refund') . hidden('id',$row['id']) ?><?php select_field('decision','Refund decision',['approve'=>'Approve refund','reject'=>'Reject request']);field('current_password','Your administrator password','','password',['required'=>'required']);button('Confirm decision','small','shield'); ?></form><?php endif ?><p class="hint"><?= t('External top-ups cannot be manually marked paid. Refunds here return local assets, not funds through a merchant gateway.') ?></p></details></td>
<?php elseif ($tab==='ledger'): ?><td>#<?= (int)$row['id'] ?> / <?= (int)$row['user_id'] ?></td><td><?= dt((int)$row['created_at'],'Y.m.d H:i') ?></td><td><?= t($row['currency']) ?></td><td class="<?= (int)$row['delta']>0?'positive':'negative' ?>"><?= (int)$row['delta']>0?'+':'' ?><?= e(price((int)$row['delta'],$row['currency'])) ?><small><?= e(price((int)$row['balance_after'],$row['currency'])) ?></small></td><td><?= t($row['reason']) ?><small><?= e($row['idempotency_key']) ?></small></td>
