<?php elseif ($tab==='logs'): ?><td>#<?= (int)$row['id'] ?></td><td>#<?= (int)$row['actor_id'] ?></td><td><?= t($row['action']) ?></td><td><?= e($row['target']) ?></td><td><?= dt((int)$row['created_at'],'Y.m.d H:i:s') ?></td>
<?php elseif ($tab==='withdrawals'): ?><td>#<?= (int)$row['id'] ?> / <?= (int)$row['user_id'] ?></td><td><?= e(price((int)$row['amount'],$row['currency'])) ?><small><?= t($row['currency']) ?></small></td><td><span class="pill"><?= t($row['status']) ?></span><small><?= e($row['note']) ?></small></td><td><?= nl2br(e($a->crypto->open($row['account_cipher']))) ?></td><td><?php if ($row['status']==='pending'): ?><details><summary><?= t('Review') ?></summary><?= form_start('admin_withdrawal') . hidden('id',$row['id']) ?><?php select_field('decision','Decision',['reject'=>'Reject and release the original held asset','paid'=>'I have paid the recipient externally']);field('note','Payout reference or rejection reason','','text',['required'=>'required']);field('current_password','Your administrator password','','password',['required'=>'required']);button('Confirm decision','small','shield'); ?></form></details><?php endif ?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div><?php if (!$rows) {empty_state();} partial('pagination',['tab'=>$tab,'pagination'=>$pagination]); ?></section>
